/// Game-wide constants for Harita: Kendi İmparatorluğunu Kur.
///
/// All magic numbers used across the codebase should be referenced
/// from this file to ensure consistency and ease of configuration.
library;

// ─── Map ────────────────────────────────────────────────────────────────────

/// Total number of cities (territories) on the Africa map: every country
/// holds four cities (the smallest ones two or three).
///
/// Must match `assets/maps/territory_graph.json`, which is generated by
/// `tool/generate_africa_map.py`.
const int kTerritoryCount = 185;

/// Fewest soldiers at game start in a city outside the start countries — a
/// bot's (or, with fewer bots, nobody's) — ("50'den aşağı olmasın").
const int kNeutralCityMinUnits = 50;

/// Most soldiers at game start in a city outside the start countries ("70'i
/// geçmesin").
const int kNeutralCityMaxUnits = 70;

/// Soldiers in each city of an army's start country.
const int kStartUnitsPerCity = 60;

/// Soldiers in each city of the player's America at game start: America is
/// surrounded by six bots, so it starts much stronger than a bot country.
const int kPlayerStartUnitsPerCity = 150;

/// Reserve soldiers every army starts with.
const int kStartUnitPool = 20;

/// Most bots that can join a game ("6 kişi").
const int kMaxBots = 6;

// ─── Base capacities ────────────────────────────────────────────────────────

/// Maximum unit capacity for a Big Base territory.
const int kBigBaseCapacity = 150;

// ─── Weapon Shop unlock turns ───────────────────────────────────────────────────

/// Turn from which the Bombardment card is sold in the Weapon Shop (it can
/// still come from the free draw earlier).
const int kTurnUnlockBombardment = 10;

/// Turn from which the Soldier Spell card is sold in the Weapon Shop.
const int kTurnUnlockSoldierSpell = 12;

/// Turn from which the Mega Bomba card is sold in the Weapon Shop.
const int kTurnUnlockMegaBomba = 45;

/// Turn from which the Atom Bomb card is sold in the Weapon Shop.
const int kTurnUnlockAtomBomb = 20;

/// Turn from which the Nuclear Bomb card is sold in the Weapon Shop.
const int kTurnUnlockNuclearBomb = 30;

// ─── Economy ─────────────────────────────────────────────────────────────────

/// Diamonds (Elmas) every army earns at the end of each of its turns.
const int kDiamondsPerTurn = 80;

/// Diamonds earned for capturing a city with a diamond mine.
const int kDiamondMineReward = 250;

/// Diamonds earned for capturing a base: every base (the yellow markers) is
/// a gold mine ("altın madeni"), worth less than a diamond mine.
const int kGoldMineReward = 150;

/// Diamonds every army starts the game with.
const int kStartDiamonds = 50;

/// Soldier units added to the unit pool at the end of each turn.
const int kSoldiersPerTurn = 15;

/// Extra soldiers per turn for every city owned.
const int kSoldiersPerCity = 4;

/// Extra soldiers per turn granted to the bot on "Zor" (hard) difficulty.
const int kHardAiBonusSoldiers = 4;

// ─── Bomb cards ─────────────────────────────────────────────────────────────

/// Soldiers the Fire Bomb kills in 1 city.
const int kFireBombDamage = 30;

/// Soldiers the Bombardment kills in each of 2 cities.
const int kBombardmentDamage = 40;

/// Soldiers the Mega Bomba kills in each of 3 cities.
const int kMegaBombaDamage = 60;

/// Soldiers the Atom Bomb ("Atom Bombası") kills in each of 4 cities,
/// anywhere on the map.
const int kAtomBombDamage = 80;

/// Soldiers the Nuclear Bomb ("Nükleer Bomba") kills in each of 6 cities,
/// anywhere on the map.
const int kNuclearBombDamage = 100;

/// Diamonds the "Haraç Kes" card takes from the target city's owner.
const int kTributeDiamonds = 200;

/// First turn on which the free draw ("Kart Çek") can give an Atom or a
/// Nuclear Bomb — before it, one lucky draw could empty a start country.
const int kTurnFirstBigBombDraw = 10;

/// Fire Bomb cards every army holds at game start.
const int kStartFireBombs = 2;

/// Soldiers a bombed city always keeps: bombs never empty a city, so land
/// is only ever taken by soldiers ("boş toprak alamasın").
const int kBombedCityMinUnits = 1;

/// Units added to a friendly city by the Soldier Spell.
const int kSoldierSpellUnits = 30;

// ─── Layout breakpoints ──────────────────────────────────────────────────────

/// Screen width (in dp) at or above which the tablet layout is used.
const double kPhoneBreakpoint = 600;

// ─── AI ──────────────────────────────────────────────────────────────────────

/// Minimum artificial delay (ms) between AI actions for visual legibility.
const int kAiActionDelayMinMs = 300;

/// Maximum artificial delay (ms) between AI actions for visual legibility.
const int kAiActionDelayMaxMs = 500;

/// Delay (ms) between AI actions once the bot has made many moves in a turn,
/// so that long turns on the big map stay quick.
const int kAiFastActionDelayMs = 60;

/// Fast delay (ms) used when more than two bots play, so a whole round of
/// up to six bots stays short.
const int kAiManyBotsFastDelayMs = 25;

/// After this many actions in one turn the bot switches to the fast delay.
const int kAiSlowActionCount = 6;

/// Minimum unit ratio (AI : enemy) required for AI to attack an enemy territory.
const double kAiAttackOddsThreshold = 1.5;

// ─── Combat ──────────────────────────────────────────────────────────────────

/// Fraction of defending units the attacker loses when winning a combat:
/// soldier for soldier, so the winner keeps the difference ("60 askerle
/// 50 askerli şehre saldırırsan 10 asker kalır").
const double kAttackerWinLossFraction = 1.0;

/// Fraction of attacking units the defender loses when holding a city:
/// soldier for soldier as well (a city always keeps at least one).
const double kDefenderHoldLossFraction = 1.0;
